control_props.onOpenChange:
(next) => {
                        if (!next) {
                            // Multi-resident: cancel returns to picker.
                            if (residents.length > 1) {
                                setSelected(null);
                            } else {
                                onOpenChange(false);
                            }
                        }
                    }

control_props.onClose:
() => {
                            setAdjustDialog({ open: false, item: null });
                            reloadInventory();
                        }

control_props.onOpenChange:
(open) => {
                            if (!open) {
                                setEditing(null);
                                return;
                            }
                            setEditing(c);
                            editForm.setData({
                                type:
                                    c.type ?? types?.[0]?.code ?? 'residential',
                                name: c.name ?? '',
                                description: c.description ?? '',
                                site_id: c.site_id ?? '',
                                is_active: !!c.is_active,
                            });
                        }
